//! RFC 4271 §4.1: every BGP message opens with a 16-octet marker that is all ones,
//! a 16-bit length covering the whole message and a one-octet type (1 OPEN,
//! 2 UPDATE, 3 NOTIFICATION, 4 KEEPALIVE; 5 ROUTE-REFRESH is RFC 2918). The
//! per-type bodies of §4.2 onwards are left opaque.
//!
//! Generated by dev/protogen from dev/protogen/specs/bgp.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{ProtoDesc, ProtoId};

// protogen:hand begin
/// RFC 4271 §4.1: Length covers the whole message, marker included.
fn content_len(hdr: &[u8]) -> usize {
    match hdr.get(16..18) {
        Some(b) => u16::from_be_bytes([b[0], b[1]]) as usize,
        None => 0,
    }
}

/// The marker is all ones on every message an RFC 4271 speaker sends, which is
/// what separates a message boundary from the middle of a stream.
pub fn looks_like(p: &[u8]) -> bool {
    p.len() >= 19 && p[..16].iter().all(|b| *b == 0xff)
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[
    FieldDesc::bytes("marker", 0, 128).defaulting_to(&[
        255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255,
    ]),
    FieldDesc::uint("len", 128, 16, 19),
    FieldDesc::uint("type", 144, 8, 4),
];

fn header_len(_: &[u8]) -> usize {
    19
}

pub static DESC: ProtoDesc = ProtoDesc {
    id: ProtoId::Bgp,
    name: "BGPHeader",
    fields: FIELDS,
    min_len: 19,
    header_len,
    next: crate::proto::next_raw,
    build_len: 19,
    parse_options: None,
    opt_table: None,
    set_hlen: None,
    bind_next: None,
    bind_next_bytes: None,
    content_len: Some(content_len),
};

#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 4271 §4.4 KEEPALIVE: the 16-octet marker, length 19, type 4.
    fn vector() -> Vec<u8> {
        vec![
            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
            0xff, 0xff, 0x00, 0x13, 0x04,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Bgp);
        let l = p.find_layer(ProtoId::Bgp).unwrap();
        assert_eq!(p.get(l, "len").unwrap(), FieldValue::Uint(19));
        assert_eq!(p.get(l, "type").unwrap(), FieldValue::Uint(4));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Bgp);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Bgp);
        let l = p.find_layer(ProtoId::Bgp).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Bgp, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
